      return {name:plan.name,strategyId:plan.strategyId,strategyVersion:plan.strategyVersion,fundCode:plan.fundCode,status:plan.status,amount:n(plan.amount),budget:n(plan.budget),dataAsOf:plan.backtestDataAsOf||performance?.dataAsOf||'',signalStatus:signal?.status||'',signalState:signal?.state||'',signalAsOf:signal?.dataAsOf||'',metrics:metricSummary(performance)};
