function showShareMarkup(){return `<div class="panda-share-head"><div><small>STRATEGY SHARE</small><h2>分享策略卡片</h2><p>图片使用当前真实回测曲线和交易点；二维码仅包含策略配置。</p></div><button type="button" data-action="close-share" aria-label="关闭">×</button></div><div class="panda-share-preview-wrap"><button type="button" class="panda-share-preview-trigger" data-action="open-share-viewer" aria-label="点击查看大图"><img id="panda-share-preview" alt="策略分享卡片预览"></button><div id="panda-share-loading">正在绘制分享图片…</div></div><div class="panda-share-actions">${button('保存图片','save-share-image','','primary')}</div><div class="panda-share-platforms"><span>使用系统分享面板</span>${button('微信聊天','platform-share','data-channel="wechat"','quiet')}${button('朋友圈','platform-share','data-channel="moments"','quiet')}</div><p class="panda-share-tip">点击后会打开 macOS 系统分享面板；在面板中选择微信，再选择聊天或朋友圈并确认。工作台不会代替你发布。</p>`}
async function openStrategyShare(item,result,planName=''){const dialog=$('#panda-share-dialog'),host=$('#panda-share-content');host.innerHTML=showShareMarkup();state.shareCard=null;if(!dialog.open)dialog.showModal();try{const card=await buildShareCard(item,result,planName),image=$('#panda-share-preview'),loading=$('#panda-share-loading');image.onload=()=>loading?.remove();image.onerror=()=>{if(loading)loading.textContent='分享图片预览载入失败，请重新打开分享。'};image.src=card.dataUrl;if(image.complete&&image.naturalWidth>0)loading?.remove()}catch(e){const loading=$('#panda-share-loading');if(loading)loading.textContent=`图片生成失败：${e.message}`;toast(e.message)}}
async function openPlanShare(id){const plan=state.plans.find(x=>x.id===id);if(!plan)throw new Error('未找到这份策略计划。');const item=findStrategy(plan.strategyId),result=shareResultForPlan(plan);if(!item)throw new Error('当前版本的策略定义不可用。');await openStrategyShare(item,result,plan.name)}
async function downloadShareCard(){const card=state.shareCard;if(!card)throw new Error('分享图片还未生成。');const filename=`${card.strategyName.replace(/[\\/:*?"<>|]/g,'-')}-策略分享.png`,saved=await desktopCall(window.fundDesktop.saveStrategyShareImage({dataUrl:card.dataUrl,filename}));if(saved.canceled)return null;card.savedPath=saved.filePath;toast('分享图片已保存。');return saved.filePath}
async function shareToChannel(channel){const card=state.shareCard;if(!card)throw new Error('分享图片还未生成。');const target={wechat:'微信聊天',moments:'朋友圈'}[channel];if(!target)throw new Error('暂不支持这个分享渠道。');const filename=(card.strategyName||'策略').replace(/[^\w\u3400-\u9fff-]/g,'-')+'-策略分享.png';await desktopCall(window.fundDesktop.shareStrategyShare({dataUrl:card.dataUrl,filename,caption:strategyShareCaption(channel,card),channel}));toast('已打开系统分享面板，请选择微信及'+target+'后确认发送。')}
function showStrategyImport(payload){if(!payload||state.shareImport&&JSON.stringify(state.shareImport)===JSON.stringify(payload))return;state.shareImport=payload;const item=findStrategy(payload.strategyId),dialog=$('#panda-share-dialog'),host=$('#panda-share-content');if(!item){host.innerHTML=`<div class="panda-share-head"><div><small>STRATEGY IMPORT</small><h2>无法识别此策略</h2><p>此工作台没有对应策略定义，或版本已不可用。</p></div><button data-action="close-share">×</button></div>`}else if(String(item.version)!==String(payload.strategyVersion)){host.innerHTML=`<div class="panda-share-head"><div><small>STRATEGY IMPORT</small><h2>策略版本已更新</h2><p>分享版本 v${esc(payload.strategyVersion)}，本机版本 v${esc(item.version)}。为避免参数含义变化，本次不自动导入。</p></div><button data-action="close-share">×</button></div>`}else{const values=(item.params||[]).map(spec=>`<span>${esc(spec.label||spec.key)} <b>${esc(payload.params?.[spec.key]??item.defaultParams?.[spec.key]??'—')}${esc(spec.unit||'')}</b></span>`).join('');host.innerHTML=`<div class="panda-share-head"><div><small>STRATEGY IMPORT</small><h2>生成同款策略</h2><p>${esc(payload.strategyName||item.name)} · ${esc(payload.fundCode||'策略默认标的')}</p></div><button data-action="close-share">×</button></div><div class="panda-import-params">${values||'<span>策略未定义可复制参数</span>'}</div><p class="panda-share-tip">只导入规则、参数与基金代码；历史回测结果不会复制，生成后需要在本机重新回测。</p><div class="panda-share-actions">${button('生成同款策略','import-strategy-share',`data-strategy="${esc(payload.strategyId)}"`,'primary')}${button('取消','close-share','','quiet')}</div>`}if(!dialog.open)dialog.showModal();if(D.enabled)desktopCall(window.fundDesktop.clearPendingStrategyShare()).catch(()=>{})}
async function importSharedStrategy(){const payload=state.shareImport,item=findStrategy(payload?.strategyId);if(!item||String(item.version)!==String(payload.strategyVersion))throw new Error('策略版本不匹配，不能安全导入。');const params={};for(const spec of item.params||[]){params[spec.key]=payload.params?.[spec.key]??item.defaultParams?.[spec.key]??spec.default}const saved=await api('/api/strategy-variants',{strategyId:item.id,name:payload.strategyName||item.name,description:`从分享卡片导入 · 基于 Skill v${item.version}`,code:payload.fundCode||'',params});state.variants=await api('/api/strategy-variants');state.variant=saved;state.selected=item.id;state.nav='library';state.result=null;state.job=null;state.pendingCode=payload.fundCode||'';state.shareImport=null;$('#panda-share-dialog').close();render();toast('同款策略已生成，正在打开详情；请重新回测确认当前数据。')}
function watchForSharedStrategy(){if(!D.enabled)return;window.fundDesktop.onStrategyShare(payload=>showStrategyImport(payload));window.fundDesktop.getPendingStrategyShare().then(desktopCall).then(payload=>{if(payload)showStrategyImport(payload)}).catch(()=>{})}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-nav],[data-session],[data-session-pin],[data-session-delete]');if(!t)return;try{if(t.dataset.nav){state.nav=t.dataset.nav;state.selected=null;state.result=null;state.runFocus=null;state.drill=null;state.agentPageFocus=null;render();if(state.nav==='plans')refreshPlanPerformance();return}if(t.dataset.session){await resumeSession(t.dataset.session);state.nav='workbench';state.selected=null;render();return}if(t.dataset.sessionPin){const row=D.sessions.find(x=>x.threadId===t.dataset.sessionPin);D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:row.threadId,pinned:!row.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current?.threadId)||D.current;renderSessions();return}if(t.dataset.sessionDelete){await deleteSession(t.dataset.sessionDelete);return}const a=t.dataset.action;if(a==='open-strategy')await openStrategy(t.dataset.id);else if(a==='share-result'){const item=findStrategy(state.selected);await openStrategyShare(item,state.result)}else if(a==='share-plan')await openPlanShare(t.dataset.id);else if(a==='save-share-image')await downloadShareCard();else if(a==='platform-share')await shareToChannel(t.dataset.channel);else if(a==='import-strategy-share')await importSharedStrategy();else if(a==='open-share-viewer'){const image=$('#panda-share-preview'),viewerImage=$('#panda-share-viewer-image'),viewer=$('#panda-share-viewer-dialog');if(image?.src){viewerImage.src=image.src;viewer.showModal()}}else if(a==='close-share-viewer')$('#panda-share-viewer-dialog').close();else if(a==='ask-agent-about-page'){state.agentPageFocus=state.drill?'fund':state.runFocus?'run':null;state.agentOpen=true;$('#panda-dialog').close();render();$('#agent-input')?.focus()}else if(a==='close-share'){state.shareImport=null;state.shareCard=null;$('#panda-share-dialog').close()}else if(a==='open-run')await openRun(t.dataset.id);else if(a==='back-library'){state.selected=null;state.variant=null;state.result=null;state.nav='library';render()}else if(a==='edit-params'){state.paramEditing=true;render()}else if(a==='cancel-param-edit'){state.paramEditing=false;render()}else if(a==='toggle-params'){state.paramsExpanded=!state.paramsExpanded;render()}else if(a==='load-variant'){state.variant=state.variants.find(x=>x.id===t.dataset.id);state.result=null;state.job=null;state.paramEditing=true;state.paramsExpanded=true;render()}else if(a==='save-plan')await savePlan();else if(a==='plan-action')await planAction(t.dataset.id,t.dataset.planAction);else if(a==='refresh-holdings'){state.holdings=null;state.analysis=null;render();loadHoldings()}else if(a==='drill-fund')await drillFund(t.dataset.code);else if(a==='close-dialog'){state.runFocus=null;state.drill=null;state.agentPageFocus=null;$('#panda-dialog').close()}else if(a==='remove-watch'){const b=await api('/api/watchlist',{code:t.dataset.code,remove:true});state.watchlist=b.watchlist||[];render()}else if(a==='pick-for-strategy'){state.pendingCode=t.dataset.code;state.nav='library';state.selected=null;$('#panda-dialog')?.close();render();toast(`已选择基金 ${t.dataset.code}，打开策略即可回测。`)}else if(a==='login-fund')await loginFund(false);else if(a==='switch-account')showAccountLoginDialog(true,true);else if(a==='confirm-switch-account')await loginFund(true)}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='panda-strategy-form'){const item=findStrategy(state.selected),intent=e.submitter?.value||'run';if(intent==='save')await saveVariant(e.target,item);else await startBacktest(e.target,item)}else if(e.target.id==='watch-form'){const raw=Object.fromEntries(new FormData(e.target)),b=await api('/api/watchlist',{code:raw.code,name:raw.name});state.watchlist=b.watchlist||[];render()}else if(e.target.id==='model-form'){const raw=Object.fromEntries(new FormData(e.target));D.settings=await desktopCall(window.fundDesktop.saveProvider({mode:'subscription',model:raw.model,effort:raw.effort}));toast('模型设置已保存，将用于新会话');render()}else if(e.target.id==='agent-form'){await sendAgent($('#agent-input').value.trim())}else if(e.target.id==='agent-question-form'){const request=D.pendingInput,form=new FormData(e.target),answers={};for(const [i,q] of (request.questions||[]).entries()){const value=String(form.get(`answer-${i}`)||'').trim();if(!value)throw new Error('请回答全部问题。');answers[q.id]={answers:[value]}}await desktopCall(window.fundDesktop.answerUserInput({requestId:request.requestId,answers}));D.pendingInput=null;renderAgentPanel()}}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{if(e.target?.name!=='model'||e.target.form?.id!=='model-form')return;const model=modelRows().find(x=>x.id===e.target.value),efforts=(model?.supportedReasoningEfforts||[]).map(x=>typeof x==='string'?x:x?.reasoningEffort).filter(Boolean),select=e.target.form.elements.effort,current=select.value;select.innerHTML=(efforts.length?efforts:['low','medium','high','xhigh']).map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(({low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'超高'})[x]||x)}</option>`).join('');if(!efforts.includes(current)&&efforts.length)select.value=efforts[0]});
document.addEventListener('click',e=>{if(!e.target.closest('#agent-page-toggle'))return;if(state.nav==='workbench'&&!state.selected){$('#agent-input')?.focus();return}if(state.nav==='holdings'&&state.holdingsAgentOpen){state.holdingsAgentOpen=false;state.agentOpen=false;render();return}state.agentOpen=!state.agentOpen;render();if(state.agentOpen)$('#agent-input')?.focus()});
document.addEventListener('click',e=>{const tab=e.target.closest('[data-holdings-tab]');if(tab){state.holdingsTab=tab.dataset.holdingsTab;render();return}const select=e.target.closest('[data-holding-select]');if(select){state.selectedHoldingCode=select.dataset.holdingSelect;render();loadHoldingDetail(state.selectedHoldingCode);return}const refresh=e.target.closest('[data-action="refresh-holding-detail"]');if(refresh){loadHoldingDetail(refresh.dataset.code,true).catch(err=>toast(err.message));return}if(e.target.closest('[data-holdings-close]')){state.holdingsAgentOpen=false;if(!D.running)state.holdingsAgentContext=null;render();return}const trigger=e.target.closest('[data-holdings-question]');if(!trigger)return;e.preventDefault();askHoldingsAgent(trigger.dataset.holdingsQuestion).catch(err=>toast(err.message))});
document.addEventListener('click',e=>{if(!e.target.closest('[data-open-holdings-agent]'))return;state.holdingsAgentContext=null;state.holdingsAgentOpen=true;render();$('#agent-input')?.focus()});
document.addEventListener('input',e=>{if(e.target?.id!=='holdings-search')return;state.holdingsSearch=e.target.value.trim().toLowerCase();let visible=false;document.querySelectorAll('.holding-fund-card').forEach(card=>{const match=(card.dataset.holdingSearch||'').includes(state.holdingsSearch);card.hidden=!match;visible=visible||match});const empty=$('#holdings-filter-empty');if(empty)empty.hidden=visible||!state.holdingsSearch});
document.addEventListener('change',e=>{if(e.target?.id!=='holdings-sort')return;state.holdingsSort=e.target.value;render()});
$('#agent-new').addEventListener('click',()=>D.enabled?newSession().catch(e=>toast(e.message)):toast('请从桌面应用启动真实 Agent。'));
$('#agent-stop').addEventListener('click',()=>window.fundDesktop.interrupt().then(desktopCall).catch(e=>toast(e.message)));
$('#agent-rename').addEventListener('click',async()=>{if(!D.current)return;const title=prompt('会话名称',D.current.title||'');if(!title?.trim())return;D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:D.current.threadId,title:title.trim()}));D.current=D.sessions.find(x=>x.threadId===D.current.threadId)||D.current;renderSessions();renderAgentPanel()});
$('#agent-pin').addEventListener('click',async()=>{if(!D.current)return;D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:D.current.threadId,pinned:!D.current.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current.threadId);renderSessions();renderAgentPanel()});
$('#agent-archive').addEventListener('click',async()=>{if(!D.current)return;D.sessions=await desktopCall(window.fundDesktop.archiveSession(D.current.threadId));D.current=null;D.messages=[];render()});
async function deleteSession(threadId){const row=D.sessions.find(x=>x.threadId===threadId);if(!row)return;if(D.running){toast('请先停止或等待当前 Agent 任务完成。');return}if(!confirm(`删除对话“${row.title}”？删除后将从历史会话中移除。`))return;const wasCurrent=D.current?.threadId===threadId,outcome=await desktopCall(window.fundDesktop.deleteSession(threadId));D.sessions=Array.isArray(outcome)?outcome:(outcome?.sessions||[]);if(wasCurrent){D.current=null;D.messages=[];D.tools.clear();D.pendingInput=null;D.turnStartedAt=null}render();if(wasCurrent&&D.sessions.length){try{await resumeSession(D.sessions[0].threadId)}catch(e){toast(`会话已删除；下一条会话加载失败：${e.message}`);return}}toast(outcome?.warning?'对话已从本机历史移除；模型服务归档暂未完成。':'对话已删除')}
$('#agent-delete').addEventListener('click',()=>D.current&&deleteSession(D.current.threadId).catch(e=>toast(e.message)));
$('#agent-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#agent-form').requestSubmit()}});

async function bootstrap(){ensureChrome();setInterval(()=>{if(D.running&&$('#agent-elapsed'))$('#agent-elapsed').textContent=Math.max(0,Math.floor((Date.now()-(D.turnStartedAt||Date.now()))/1000))+' 秒'},1000);try{await refreshLocal();render();startMonitor();loadHoldings();loadShowcases();if(D.enabled){watchForSharedStrategy();await initDesktop()}else render()}catch(e){$('#panda-content').innerHTML=`<div class="panda-empty-page"><div><div class="empty-symbol">!</div><h2>本地服务尚未启动</h2><p>${esc(e.message)}</p></div></div>`}}
bootstrap();
